#include "modelpicker.h"
#include "modelcache.h"
#include "studiobutton.h"
#include <QtWidgets>
ModelPickerDialog::ModelPickerDialog(const QString &title,const QString &current,QWidget *parent):QDialog(parent),currentPath(current){
    setWindowTitle(title);setObjectName("modelPickerWindow");resize(1000,580);auto root=new QVBoxLayout(this);auto row=new QHBoxLayout;row->addWidget(new QLabel("Каталог:"));source=new QComboBox;source->setObjectName("modelPickerSource");source->addItem("Все",QString());ModelCache cache;models=cache.allModels();for(const auto &path:cache.directories())source->addItem(QDir::toNativeSeparators(path),path);row->addWidget(source,1);auto browse=new StudioButton("Произвольный файл…");browse->setObjectName("browseAnyModelFile");row->addWidget(browse);root->addLayout(row);
    filter=new QLineEdit;filter->setObjectName("modelPickerFilter");filter->setClearButtonEnabled(true);filter->setPlaceholderText("Поиск по имени, квантованию, архитектуре или пути");root->addWidget(filter);auto note=new QLabel("Список загружен из JSON без сканирования. «Все» показывает все известные модели; каталог ограничивает список своей папкой. Для любого другого файла используйте «Произвольный файл…». Новые папки добавляются в окне «Каталог моделей».");note->setWordWrap(true);root->addWidget(note);
    table=new QTableWidget(0,5);table->setObjectName("modelPickerTable");table->setHorizontalHeaderLabels({"Модель / файл","Квантование","Размер, ГиБ","Контекст","Путь"});table->setSelectionBehavior(QAbstractItemView::SelectRows);table->setSelectionMode(QAbstractItemView::SingleSelection);table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->verticalHeader()->hide();table->horizontalHeader()->setStretchLastSection(true);table->setColumnWidth(0,260);table->setColumnWidth(1,115);table->setColumnWidth(2,115);root->addWidget(table,1);
    int selectedRow=-1;for(int i=0;i<models.size();++i){const auto &m=models[i];int r=table->rowCount();table->insertRow(r);const QStringList cells={m.name.isEmpty()?QFileInfo(m.path).fileName():m.name+" · "+QFileInfo(m.path).fileName(),modelQuantization(m.fileType),QString::number(m.fileBytes/1073741824.0,'f',3),m.trainingContext>0?QString::number(m.trainingContext):QString("—"),QDir::toNativeSeparators(m.path)};for(int c=0;c<cells.size();++c){auto item=new QTableWidgetItem(cells[c]);item->setToolTip(m.error.isEmpty()?m.path+"\n"+m.architecture:m.error);if(!m.error.isEmpty())item->setFlags(item->flags()&~Qt::ItemIsEnabled);table->setItem(r,c,item);}table->item(r,0)->setData(Qt::UserRole,i);if(QDir::fromNativeSeparators(current)==m.path)selectedRow=r;}
    status=new QLabel;status->setTextFormat(Qt::PlainText);status->setWordWrap(true);root->addWidget(status);auto footer=new QHBoxLayout;footer->addStretch();use=new StudioButton("Выбрать из списка");use->setObjectName("useCachedModel");use->setEnabled(false);footer->addWidget(use);auto cancel=new StudioButton("Отмена");footer->addWidget(cancel);root->addLayout(footer);
    connect(cancel,&QPushButton::clicked,this,&QDialog::reject);connect(use,&QPushButton::clicked,this,&ModelPickerDialog::selectModel);connect(table,&QTableWidget::itemDoubleClicked,this,[this]{selectModel();});connect(table,&QTableWidget::itemSelectionChanged,this,[this]{const auto item=table->item(table->currentRow(),0);use->setEnabled(item&&!table->isRowHidden(item->row())&&(item->flags()&Qt::ItemIsEnabled));});connect(source,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{filterRows();});connect(filter,&QLineEdit::textChanged,this,&ModelPickerDialog::filterRows);
    connect(browse,&QPushButton::clicked,this,[this]{auto path=QFileDialog::getOpenFileName(this,"Выбрать произвольный файл модели",currentPath,"Все файлы (*);;Модели GGUF (*.gguf)");if(!path.isEmpty()){selected=path;accept();}});filterRows();if(selectedRow>=0)table->selectRow(selectedRow);
}
void ModelPickerDialog::filterRows(){const auto root=QDir::fromNativeSeparators(source->currentData().toString());const auto query=filter->text().trimmed();int visible=0;for(int r=0;r<table->rowCount();++r){const auto &m=models[table->item(r,0)->data(Qt::UserRole).toInt()];const auto path=QDir::fromNativeSeparators(m.path);
#ifdef Q_OS_WIN
    const auto cs=Qt::CaseInsensitive;
#else
    const auto cs=Qt::CaseSensitive;
#endif
    const auto prefix=root.endsWith('/')?root:root+'/';const bool directory=root.isEmpty()||path.startsWith(prefix,cs);const bool match=(m.name+" "+m.path+" "+m.architecture+" "+modelQuantization(m.fileType)).contains(query,Qt::CaseInsensitive);table->setRowHidden(r,!directory||!match);if(directory&&match)++visible;}auto item=table->item(table->currentRow(),0);use->setEnabled(item&&!table->isRowHidden(item->row())&&(item->flags()&Qt::ItemIsEnabled));status->setText(QString("Из JSON: %1 моделей. Показано: %2.").arg(models.size()).arg(visible));}
void ModelPickerDialog::selectModel(){auto item=table->item(table->currentRow(),0);if(!item||table->isRowHidden(item->row())||!(item->flags()&Qt::ItemIsEnabled))return;const auto path=ModelCache::loadPath(models[item->data(Qt::UserRole).toInt()]);if(path.isEmpty()||!QFileInfo(path).isFile()){status->setText("Файл или первая часть модели недоступны. Обновите каталог моделей или выберите произвольный файл.");return;}selected=path;accept();}
QString ModelPickerDialog::choose(QWidget *parent,const QString &title,const QString &current){ModelCache cache;if(cache.allModels().isEmpty())return QFileDialog::getOpenFileName(parent,title,current,"Все файлы (*);;Модели GGUF (*.gguf)");ModelPickerDialog picker(title,current,parent);return picker.exec()==QDialog::Accepted?picker.selectedPath():QString();}
